// Deadband constants must match utils/sysid_utils.py
constexpr float DEADBAND_VEL = 0.02f;
constexpr float DEADBAND_ACC = 0.05f;

inline float mlp_deadband_vel(float v) {
    return (v > -DEADBAND_VEL && v < DEADBAND_VEL) ? 0.0f : v;
}
inline float mlp_deadband_acc(float a) {
    return (a > -DEADBAND_ACC && a < DEADBAND_ACC) ? 0.0f : a;
}
inline float mlp_sign_vel(float v) {
    if (v > -DEADBAND_VEL && v < DEADBAND_VEL) return 0.0f;
    return (v > 0.0f) ? 1.0f : -1.0f;
}
inline float mlp_leaky(float x) { return (x > 0.0f) ? x : (0.01f * x); }

