static const float b2_ANG_HYP[] = {-0.055629f,-0.031080f,0.094812f,-0.085593f,0.209133f,0.139870f,0.113782f,-0.011889f,0.190113f,-0.112193f,-0.080886f,0.084992f,0.041119f,0.024067f,0.246215f,-0.066958f,0.263653f,0.433965f,0.088696f,0.098592f,-0.107234f,0.068812f,-0.113548f,-0.033070f,0.002845f,0.232367f,-0.003642f,0.184145f,-0.026757f,-0.096887f,0.013732f,0.010983f};
static const float w3_ANG_HYP[] = {-1.343190f,0.601085f,0.891339f,-1.339691f,1.050735f,0.690871f,0.743458f,-1.405119f,0.966579f,2.025432f,-1.327317f,-1.437395f,-1.290164f,0.784450f,1.247416f,-1.222611f,1.085071f,1.141361f,1.718356f,1.011506f,-1.056539f,1.861928f,-1.168052f,-1.454940f,-1.467268f,1.142847f,-1.499018f,1.437370f,1.126663f,0.257352f,1.059875f,-1.210657f};
static const float b3_ANG_HYP[] = {-0.123240f};

inline float mlp_predict_ang(float omega, float alpha, float sign_omega, float abs_lin_vel, float abs_lin_accel, float turn_radius) {
    float v = mlp_deadband_vel(omega);
    float a = mlp_deadband_acc(alpha);
    float s = (sign_omega != 0.0f) ? sign_omega : mlp_sign_vel(omega);
    float abs_lin = (abs_lin_vel < 0.0f) ? -abs_lin_vel : abs_lin_vel;
    float abs_acc = (abs_lin_accel < 0.0f) ? -abs_lin_accel : abs_lin_accel;
    float turn_r = (turn_radius < 0.0f) ? -turn_radius : turn_radius;
    float abs_om = (omega < 0.0f) ? -omega : omega;
    float interaction = abs_lin * abs_om;
    float centripetal = abs_om * abs_om * turn_r;
    float out_a, out_b, hyper_logit;
    {    float h1[MLP_H1_ANG_A];
    for (int i = 0; i < MLP_H1_ANG_A; i++) {
        float sum = b1_ANG_A[i] + (v * w1_ANG_A[i*8]) + (a * w1_ANG_A[i*8+1]) + (s * w1_ANG_A[i*8+2]) + (abs_lin * w1_ANG_A[i*8+3]) + (abs_acc * w1_ANG_A[i*8+4]) + (turn_r * w1_ANG_A[i*8+5]) + (interaction * w1_ANG_A[i*8+6]) + (centripetal * w1_ANG_A[i*8+7]);
        h1[i] = mlp_leaky(sum);
    }
    float h2[MLP_H2_ANG_A];
    for (int i = 0; i < MLP_H2_ANG_A; i++) {
        float sum = b2_ANG_A[i];
        for (int j = 0; j < MLP_H1_ANG_A; j++) sum += h1[j] * w2_ANG_A[i*MLP_H1_ANG_A + j];
        h2[i] = mlp_leaky(sum);
    }
    float out = b3_ANG_A[0];
    for (int i = 0; i < MLP_H2_ANG_A; i++) out += h2[i] * w3_ANG_A[i];
    out_a = out;
    }
    {    float h1[MLP_H1_ANG_B];
    for (int i = 0; i < MLP_H1_ANG_B; i++) {
        float sum = b1_ANG_B[i] + (v * w1_ANG_B[i*8]) + (a * w1_ANG_B[i*8+1]) + (s * w1_ANG_B[i*8+2]) + (abs_lin * w1_ANG_B[i*8+3]) + (abs_acc * w1_ANG_B[i*8+4]) + (turn_r * w1_ANG_B[i*8+5]) + (interaction * w1_ANG_B[i*8+6]) + (centripetal * w1_ANG_B[i*8+7]);
        h1[i] = mlp_leaky(sum);
    }
    float h2[MLP_H2_ANG_B];
    for (int i = 0; i < MLP_H2_ANG_B; i++) {
        float sum = b2_ANG_B[i];
        for (int j = 0; j < MLP_H1_ANG_B; j++) sum += h1[j] * w2_ANG_B[i*MLP_H1_ANG_B + j];
        h2[i] = mlp_leaky(sum);
    }
    float out = b3_ANG_B[0];
    for (int i = 0; i < MLP_H2_ANG_B; i++) out += h2[i] * w3_ANG_B[i];
    out_b = out;
    }
    {    float h1[MLP_H1_ANG_HYP];
    for (int i = 0; i < MLP_H1_ANG_HYP; i++) {
        float sum = b1_ANG_HYP[i] + (v * w1_ANG_HYP[i*8]) + (a * w1_ANG_HYP[i*8+1]) + (s * w1_ANG_HYP[i*8+2]) + (abs_lin * w1_ANG_HYP[i*8+3]) + (abs_acc * w1_ANG_HYP[i*8+4]) + (turn_r * w1_ANG_HYP[i*8+5]) + (interaction * w1_ANG_HYP[i*8+6]) + (centripetal * w1_ANG_HYP[i*8+7]);
        h1[i] = mlp_leaky(sum);
    }
    float h2[MLP_H2_ANG_HYP];
    for (int i = 0; i < MLP_H2_ANG_HYP; i++) {
        float sum = b2_ANG_HYP[i];
        for (int j = 0; j < MLP_H1_ANG_HYP; j++) sum += h1[j] * w2_ANG_HYP[i*MLP_H1_ANG_HYP + j];
        h2[i] = mlp_leaky(sum);
    }
    float out = b3_ANG_HYP[0];
    for (int i = 0; i < MLP_H2_ANG_HYP; i++) out += h2[i] * w3_ANG_HYP[i];
    hyper_logit = out;
    }
    float w_a = 1.0f / (1.0f + std::exp(-hyper_logit / 0.800000f));
    return w_a * out_a + (1.0f - w_a) * out_b;
}
